using System;using System.IO;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Threading;using RingTimer;
class DemoCapture {
 static void Pump(int ms){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 [STAThread]static void Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application();Theme.ApplyGlobalResources(app);Theme.Apply(true,null,null,null);L.SetLanguage("en");var content=new StackPanel{Margin=new Thickness(24)};content.Children.Add(Theme.Text("Drag to explore",18,Theme.Foreground));var rail=new SlidingRail("日历","总量","分段"){Margin=new Thickness(0,18,0,24)};content.Children.Add(rail);var button=Theme.Button("开始工作",true);content.Children.Add(button);var panel=new Border{Width=326,Height=208,Background=Theme.Background,CornerRadius=new CornerRadius(20),Child=content};var w=new Window{Content=panel,SizeToContent=SizeToContent.WidthAndHeight,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=System.Windows.Media.Brushes.Transparent,Left=-2000,Top=0,ShowInTaskbar=false};w.Show();Pump(300);
 for(int i=0;i<150;i++){if(i==15)rail.BeginGesture(260);if(i==42)rail.MoveGesture(50);if(i==65)rail.MoveGesture(145);if(i==90)rail.EndGesture(true);if(i==110)button.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=UIElement.PreviewMouseLeftButtonDownEvent});if(i==122)button.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=UIElement.PreviewMouseLeftButtonUpEvent});Pump(33);Theme.Snapshot(panel,Path.Combine(args[0],i.ToString("000")+".png"),1.5);}w.Close();app.Shutdown();File.WriteAllText(Path.Combine(args[0],"done.txt"),"150 native WPF frames captured");}
}
